use std::path::Path;use artifactum_core::{provider_error,AcquireContext,Acquisition,AcquisitionPlan,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,Resolution,ResolvedFile};use artifactum_provider_command::{find_and_copy,required_fragment,run_checked,single_file_resolution,source_with,string_field,tempdir};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct ClearMlProvider;
#[async_trait]impl ArtifactProvider for ClearMlProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"clearml".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["clearml".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,list:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,_:&ResolveContext)->artifactum_core::Result<Resolution>{let(kind,rest)=r.reference.locator().split_once(':').ok_or_else(||provider_error("clearml","expected clearml:dataset:<id>#<path>"))?;if kind!="dataset"{return Err(provider_error("clearml","only dataset references are supported in this provider version"));}let(id,path)=required_fragment("clearml",rest,"path")?;single_file_resolution("clearml",format!("clearml:dataset:{id}#{path}"),r,path,source_with([("dataset_id",id.into()),("path",path.into())]))}async fn prepare_acquisition(&self,f:&ResolvedFile,_:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{Ok(AcquisitionPlan::ProviderManaged{state:f.source.clone()})}async fn acquire_managed(&self,f:&ResolvedFile,_:&AcquisitionPlan,d:&Path,_:&AcquireContext)->artifactum_core::Result<Acquisition>{let id=string_field(&f.source,"dataset_id","clearml")?;let path=string_field(&f.source,"path","clearml")?;let tmp=tempdir("clearml")?;run_checked("clearml","clearml-data",["get","--id",id,"--copy",tmp.path().to_str().unwrap_or("."),"--overwrite"]).await?;let n=find_and_copy(tmp.path(),path,d,"clearml").await?;Ok(Acquisition{bytes_written:Some(n),metadata:Default::default()})}}
pub fn provider()->ClearMlProvider{ClearMlProvider}
